import json

# Load changelog data from JSON file
with open('changelog.json', 'r') as f:
    changelog_data = json.load(f)

# Function to filter changelog entries
def filter_changelog(data, category=None, date=None):
    filtered_entries = data

    if category:
        filtered_entries = [entry for entry in filtered_entries if entry['category'] == category]
    if date:
        filtered_entries = [entry for entry in filtered_entries if entry['date'] == date]

    return filtered_entries

